<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('documents.view');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$id=(int)($_GET['id']??$_POST['id']??0);$st=db()->prepare("SELECT d.*,p.name patient_name,p.primary_professional_id,u.name professional_name,u.professional_crp,t.name tenant_name FROM clinical_documents d JOIN patients p ON p.id=d.patient_id AND p.tenant_id=d.tenant_id JOIN users u ON u.id=d.professional_id AND u.tenant_id=d.tenant_id JOIN tenants t ON t.id=d.tenant_id WHERE d.id=:id AND d.tenant_id=:t");$st->execute(['id'=>$id,'t'=>$user['tenant_id']]);$d=$st->fetch();if(!$d||!\App\Core\Rbac::canViewPatientClinical($user,$d)){http_response_code(403);require APP_ROOT.'/app/views/403.php';exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='compliance'&&in_array($d['status'],['draft','pending_approval','approved'],true)){db()->prepare("UPDATE clinical_documents SET compliance_status='reviewed',updated_at=NOW() WHERE id=:id AND tenant_id=:t")->execute(['id'=>$id,'t'=>$user['tenant_id']]);audit('clinical.document_compliance_review','clinical_document',$id,[]);redirect('documents/view.php?id='.$id);}if($action==='approve'&&$d['status']==='pending_approval'&&(int)$d['supervisor_id']===(int)$user['id']&&\App\Core\Rbac::allows((int)$user['id'],'clinical.approve')){db()->prepare("UPDATE clinical_documents SET status='signed',approved_by=:u,signed_at=NOW(),updated_at=NOW() WHERE id=:id AND tenant_id=:t")->execute(['u'=>$user['id'],'id'=>$id,'t'=>$user['tenant_id']]);audit('clinical.document_cosign','clinical_document',$id,[]);redirect('documents/view.php?id='.$id);}if($action==='sign'&&(int)$d['professional_id']===(int)$user['id']&&$user['role_slug']!=='supervised'&&in_array($d['status'],['draft','approved'],true)){db()->prepare("UPDATE clinical_documents SET status='signed',signed_at=NOW(),updated_at=NOW() WHERE id=:id AND tenant_id=:t")->execute(['id'=>$id,'t'=>$user['tenant_id']]);audit('clinical.document_sign','clinical_document',$id,[]);redirect('documents/view.php?id='.$id);}}$content=\App\Core\Crypto::decrypt($d['content_enc'],true);audit('clinical.document_view','clinical_document',$id,[]);layout('Documento',function()use($d,$content,$user){?><div class="page-head"><div><span class="eyebrow"><?=e(ucfirst($d['document_type']))?></span><h1><?=e($d['title'])?></h1><p data-private><?=e($d['patient_name'])?> · <?=e($d['professional_name'])?> · <span class="status <?=e($d['status'])?>"><?=e($d['status'])?></span></p></div><div class="split-actions"><a class="button ghost" href="<?=e(url('ai/index.php?mode=audit&document_id='.$d['id']))?>">Auditar com IA</a><?php if($d['status']==='signed'):?><a class="button secondary" target="_blank" href="<?=e(url('documents/print.php?id='.$d['id']))?>">Imprimir / PDF</a><?php endif?></div></div><section class="card stack"><?php foreach($content as $k=>$v):?><article><small class="eyebrow"><?=e(ucfirst(str_replace('_',' ',$k)))?></small><p data-private style="line-height:1.8"><?=nl2br(e($v))?></p></article><?php endforeach?><hr><div class="split-actions"><span class="status">Conformidade: <?=e($d['compliance_status'])?></span><?php if($d['compliance_status']!=='reviewed'&&$d['status']!=='signed'):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$d['id']?>"><button class="button ghost small" name="action" value="compliance">Marcar revisão humana concluída</button></form><?php endif?><?php if((int)$d['professional_id']===(int)$user['id']&&$user['role_slug']!=='supervised'&&in_array($d['status'],['draft','approved'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$d['id']?>"><button class="button" name="action" value="sign">Assinar documento</button></form><?php endif?><?php if($d['status']==='pending_approval'&&(int)$d['supervisor_id']===(int)$user['id']&&\App\Core\Rbac::allows((int)$user['id'],'clinical.approve')):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$d['id']?>"><button class="button" name="action" value="approve">Revisar e coassinar</button></form><?php endif?></div><?php if($d['status']==='signed'):?><p class="help">Validação pública: <?=e(url('validate.php?token='.$d['validation_token']))?></p><?php endif?></section><?php },['active'=>'documents']);
